Schueler s = new Schueler("Lena", 2);
Console.WriteLine($"{s.Name}: {s.Note}");
// Ausgabe: Lena: 2

class Schueler
{
    public string Name;
    public int Note;

    public Schueler(string name, int note)
    {
        Name = name;
        Note = note;
    }
}

Haustier h = new Haustier("Minka", 3);
h.Vorstellen();
// Ausgabe: Ich bin Minka und 3 Jahre alt.

class Haustier
{
    public string name;
    public int alter;

    public Haustier(string name, int alter)
    {
        this.name = name;
        this.alter = alter;
    }

    public void Vorstellen()
    {
        Console.WriteLine($"Ich bin {name} und {alter} Jahre alt.");
    }
}

// Fehler! Die Klasse hat nur einen Konstruktor mit zwei Parametern:
