Spielfigur held = new Spielfigur("Aria", 150);
Spielfigur gegner = new Spielfigur("Goblin");

Console.WriteLine($"{held.Name} hat {held.Leben} Leben.");
Console.WriteLine($"{gegner.Name} hat {gegner.Leben} Leben.");
// Ausgabe:
// Aria hat 150 Leben.
// Goblin hat 100 Leben.

class Spielfigur
{
    public string Name;
    public int Leben;

    public Spielfigur(string name, int leben)
    {
        Name = name;
        Leben = leben;
    }

    // Ohne Angabe gibt es 100 Leben
    public Spielfigur(string name) : this(name, 100)
    {
    }
}

